  if(key==="filter-0"){$$('[data-quick]').forEach(button=>button.onclick=()=>{const status=button.dataset.quick;$$('[data-quick]').forEach(x=>x.classList.toggle('active',x===button));let count=0;$$('.quick-filter li').forEach(row=>{const visible=status==='全部'||row.dataset.status===status;row.hidden=!visible;if(visible)count++;});$('.quick-filter p').textContent='共 '+count+' 条';say('已筛选：'+status);});}
  if(key==="filter-1"){$$('.logic-toggle button').forEach(button=>button.onclick=()=>{$$('.logic-toggle button').forEach(x=>x.classList.toggle('active',x===button));$('.builder-filter p').textContent='符合'+(button.textContent==='AND'?'全部':'任一')+'条件';say('已切换为 '+button.textContent+' 逻辑');});bindCycleButtons($$('.condition [data-values]'),say);$('.add-condition').onclick=()=>{const condition=$('.condition').cloneNode(true);condition.querySelector('.remove-condition').onclick=()=>{condition.remove();say('已删除条件');};$('.add-condition').before(condition);bindCycleButtons([...condition.querySelectorAll('[data-values]')],say);say('已添加一条条件');};$('.remove-condition').onclick=e=>{if($$('.condition').length>1)e.currentTarget.closest('.condition').remove();else say('至少保留一条条件');};}
  if(key==="filter-2"){bindCycleButtons($$('.global-controls [data-values]'),text=>{const controls=$$('.global-controls button').map(x=>x.textContent);$('.global-filter p').textContent=controls.join(' · ');const factor=controls.includes('华东')?.72:controls.includes('华南')?.58:1;$('.global-cards article:first-child b').textContent=Math.round(286*factor)+' 万';say('全局条件已更新，全部卡片同步刷新');});}
