function bindTableSort(root,say){const button=root.querySelector('[data-sort]'),body=root.querySelector('tbody'),original=[...body.rows],states=['default','asc','desc'];let index=0;button.onclick=()=>{index=(index+1)%3;const state=states[index],rows=state==='default'?original:[...original].sort((a,b)=>(Number(a.dataset.value)-Number(b.dataset.value))*(state==='asc'?1:-1));rows.forEach(row=>body.append(row));button.querySelector('i').textContent=state==='asc'?'↑':state==='desc'?'↓':'↕';say(state==='default'?'已恢复默认顺序':'收入已'+(state==='asc'?'升序':'降序')+'排列');};}
