function bindColumnResize(root,say){const column=root.querySelector('.resize-col'),handle=column.querySelector('button'),label=root.querySelector('p');let start=0,width=0;handle.onpointerdown=e=>{start=e.clientX;width=column.offsetWidth;handle.setPointerCapture(e.pointerId);};handle.onpointermove=e=>{if(!handle.hasPointerCapture(e.pointerId))return;const next=Math.max(95,Math.min(210,width+e.clientX-start));column.style.width=next+'px';root.querySelector('.resize-table-wrap').style.gridTemplateColumns=next+'px 1fr 1fr';label.textContent='拖动表头分隔线 · '+Math.round(next)+' px';};handle.onpointerup=e=>{handle.releasePointerCapture(e.pointerId);say('列宽已保存为 '+Math.round(column.offsetWidth)+' px');};}
function makeBrushDetails(root,say){const chart=root.querySelector('.mini-brush'),range=root.querySelector('.brush-window'),rows=root.querySelector('.detail-rows'),label=root.querySelector('p');let start=null;chart.onpointerdown=e=>{const r=chart.getBoundingClientRect();start=e.clientX-r.left;chart.setPointerCapture(e.pointerId);range.style.left=start+'px';range.style.width='0';};chart.onpointermove=e=>{if(start===null||!chart.hasPointerCapture(e.pointerId))return;const x=e.clientX-chart.getBoundingClientRect().left;range.style.left=Math.min(start,x)+'px';range.style.width=Math.abs(x-start)+'px';};chart.onpointerup=e=>{chart.releasePointerCapture(e.pointerId);start=null;rows.classList.add('filtered');label.textContent='选区命中 2 条明细';say('图表选区已联动下方 2 条明细');};}
function updateFilterTags(root,say){const count=root.querySelectorAll('[data-tag]').length;root.querySelector('.filter-result b').textContent=count?String(35+count*17):'286';root.querySelector('.filter-result span').textContent=count?'条匹配记录':'条全部记录';say(count?'当前还有 '+count+' 个筛选条件':'已清空全部条件');}

function bindCascader(root,say){
  const $=selector=>root.querySelector(selector), $$=selector=>[...root.querySelectorAll(selector)];
  const state={province:0,city:0,area:null};
  const result=$('.demo-result'),search=$('.cascade-search'),matches=$('.cascade-matches');
  const path=()=>[locationTree[state.province].name,locationTree[state.province].children[state.city].name,state.area].filter(Boolean);
  const render=()=>{
    const province=locationTree[state.province],city=province.children[state.city];
    $('.provinces').innerHTML=locationTree.map((p,i)=>`<button data-province="${i}" class="${i===state.province?'chosen':''}">${p.name}<b>›</b></button>`).join('');
    $('.cities').innerHTML=province.children.map((c,i)=>`<button data-city="${i}" class="${i===state.city?'chosen':''}">${c.name}<b>›</b></button>`).join('');
    $('.areas').innerHTML=city.children.map(area=>`<button data-area="${area}" class="${area===state.area?'chosen':''}">${area}</button>`).join('');
    $$('[data-province]').forEach(b=>b.onclick=()=>{state.province=Number(b.dataset.province);state.city=0;state.area=null;render();result.textContent=`当前选择：${locationTree[state.province].name}`;say('上级已切换，下级选项已更新');});
    $$('[data-city]').forEach(b=>b.onclick=()=>{state.city=Number(b.dataset.city);state.area=null;render();result.textContent=`当前选择：${path().join(' / ')}`;say('城市已切换，区县选项已更新');});
    $$('[data-area]').forEach(b=>b.onclick=()=>{state.area=b.dataset.area;render();result.textContent=`已选择：${path().join(' / ')}`;say(`已选择：${state.area}`);});
  };
  const showMatches=paths=>{matches.innerHTML=paths.length?pathButtons(paths):'<p>没有匹配地区</p>';matches.classList.add('show');$$('.cascade-matches button').forEach(b=>b.onclick=()=>{const selected=b.dataset.path.split('|'),pIndex=locationTree.findIndex(p=>p.name===selected[0]);state.province=pIndex;state.city=locationTree[pIndex].children.findIndex(c=>c.name===selected[1]);state.area=selected[2];search.value=selected.at(-1);matches.classList.remove('show');render();result.textContent=`已选择：${selected.join(' / ')}`;say(`已匹配并选择：${selected.at(-1)}`);});};
  search.oninput=()=>{const keyword=search.value.trim().toLowerCase();if(!keyword){matches.classList.remove('show');return;}showMatches(locationPaths.filter(item=>item.join(' ').toLowerCase().includes(keyword)));};
  search.onfocus=()=>{if(search.value.trim())search.oninput();};
  render();
}

function bindCycleButtons(buttons,say){buttons.forEach(button=>button.onclick=()=>{const values=button.dataset.values.split('|'),next=(values.indexOf(button.textContent.trim())+1)%values.length;button.textContent=values[next];say(`已切换为：${values[next].replace('⌄','')}`);});}
function bindPanZoom(root,say){let scale=1,offset=0;const windowEl=root.querySelector('.panzoom-window'),label=root.querySelector('.panzoom-chart p'),apply=()=>{windowEl.style.setProperty('--scale',scale);windowEl.style.setProperty('--offset',offset+'px');const months=Math.max(3,Math.round(6/scale)),start=Math.max(1,Math.min(12-months+1,1+Math.round(-offset/35)));label.textContent='当前范围：'+start+' 月 — '+(start+months-1)+' 月';say(label.textContent);};root.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>{const action=button.dataset.action;if(action==='in')scale=Math.min(2,scale+.25);if(action==='out')scale=Math.max(1,scale-.25);if(action==='left')offset=Math.min(0,offset+35);if(action==='right')offset=Math.max(-210,offset-35);if(action==='reset'){scale=1;offset=0;}apply();});let startX=null;windowEl.onpointerdown=e=>{startX=e.clientX;windowEl.setPointerCapture(e.pointerId);};windowEl.onpointermove=e=>{if(startX===null||!windowEl.hasPointerCapture(e.pointerId))return;offset=Math.max(-210,Math.min(0,offset+e.clientX-startX));startX=e.clientX;apply();};windowEl.onpointerup=e=>{windowEl.releasePointerCapture(e.pointerId);startX=null;};apply();}
function makeContextWindow(root,say){const selection=root.querySelector('.context-selection'),title=root.querySelector('.focus-title'),track=root.querySelector('.context-track');let start=null;selection.onpointerdown=e=>{start=e.clientX;selection.setPointerCapture(e.pointerId);};selection.onpointermove=e=>{if(start===null||!selection.hasPointerCapture(e.pointerId))return;const max=track.clientWidth-selection.offsetWidth,left=Math.max(0,Math.min(max,selection.offsetLeft+e.clientX-start));selection.style.left=left+'px';start=e.clientX;const month=Math.round(left/Math.max(1,max)*5)+1;title.textContent='主图 · '+month+' 月至 '+(month+6)+' 月';say('上下文窗口已移动到 '+month+' 月至 '+(month+6)+' 月');};selection.onpointerup=e=>{selection.releasePointerCapture(e.pointerId);start=null;};}
function bindPlayback(root,say){const input=root.querySelector('input'),label=root.querySelector('.playback-controls b'),button=root.querySelector('.play-toggle'),bars=[...root.querySelectorAll('.playback-bars i')];let timer=null;const update=()=>{const step=Number(input.value);label.textContent=(step+1)+' 月';bars.forEach((bar,i)=>bar.classList.toggle('current',i===step));say('当前播放到 '+label.textContent);};const stop=()=>{clearInterval(timer);timer=null;button.textContent='▶';};button.onclick=()=>{if(timer){stop();say('已暂停');return;}button.textContent='Ⅱ';timer=setInterval(()=>{input.value=(Number(input.value)+1)%5;update();},500);say('开始播放');};input.oninput=()=>{stop();update();};update();}
function bindHistory(root,say){const states=['初始视图'],future=[],$=selector=>root.querySelector(selector),update=()=>{$('[data-history="undo"]').disabled=states.length===1;$('[data-history="redo"]').disabled=future.length===0;$('.history-chart p').textContent=states.at(-1);};root.querySelectorAll('.history-bars button').forEach(button=>button.onclick=()=>{states.push('筛选：'+button.dataset.value);future.length=0;root.dataset.selected=button.dataset.value;say(states.at(-1));update();});$('[data-history="undo"]').onclick=()=>{if(states.length>1){future.push(states.pop());delete root.dataset.selected;say('已撤销');update();}};$('[data-history="redo"]').onclick=()=>{if(future.length){states.push(future.pop());say('已重做');update();}};$('[data-history="reset"]').onclick=()=>{states.splice(1);future.length=0;delete root.dataset.selected;say('已恢复初始视图');update();};update();}
function bindHierarchy(root,say){const crumb=root.querySelector('.hierarchy-crumb'),tree=root.querySelector('.treemap'),data={电商:['服饰','数码','家居'],广告:['搜索','信息流','品牌'],服务:['咨询','交付','续费']};const renderRoot=()=>{crumb.querySelector('span').textContent='';tree.innerHTML='<button data-node="电商" class="tree-a">电商</button><button data-node="广告" class="tree-b">广告</button><button data-node="服务" class="tree-c">服务</button>';bindNodes();};const bindNodes=()=>tree.querySelectorAll('[data-node]').forEach(button=>button.onclick=()=>{const children=data[button.dataset.node];if(!children)return;crumb.querySelector('span').textContent='› '+button.dataset.node;tree.innerHTML=children.map((name,i)=>'<button class="tree-'+String.fromCharCode(97+i)+'">'+name+'</button>').join('');say('已放大到：'+button.dataset.node);});crumb.querySelector('button').onclick=()=>{renderRoot();say('已返回全部业务');};renderRoot();}
function bindNetwork(root,say){const nodes=[...root.querySelectorAll('[data-node]')],edges=[...root.querySelectorAll('[data-edge]')],adjacent={a:['a','b','c'],b:['a','b','d'],c:['a','c'],d:['b','d']};nodes.forEach(node=>node.onclick=()=>{const id=node.dataset.node;root.dataset.focus=id;nodes.forEach(n=>n.classList.toggle('dim',!adjacent[id].includes(n.dataset.node)));edges.forEach(edge=>edge.classList.toggle('dim',!edge.dataset.edge.includes(id)));say('已聚焦节点 '+id.toUpperCase()+' 及其直接邻居');});root.querySelector('svg').onclick=e=>{if(e.target.tagName==='svg'){delete root.dataset.focus;nodes.forEach(n=>n.classList.remove('dim'));edges.forEach(edge=>edge.classList.remove('dim'));say('已恢复全部关系');}};}
function bindKeyboardChart(root,say){const bars=[...root.querySelectorAll('[data-index]')];let index=0;const focus=()=>{bars.forEach((bar,i)=>bar.classList.toggle('focused',i===index));bars[index].focus();say('当前 '+bars[index].textContent);};root.onkeydown=e=>{if(e.key==='ArrowRight'){e.preventDefault();index=(index+1)%bars.length;focus();}if(e.key==='ArrowLeft'){e.preventDefault();index=(index-1+bars.length)%bars.length;focus();}if(e.key==='Enter'){bars[index].classList.toggle('selected');say(bars[index].textContent+(bars[index].classList.contains('selected')?' 已选择':' 已取消'));}if(e.key==='Escape'){bars.forEach(b=>b.classList.remove('selected','focused'));say('已清除选择');}};bars.forEach((bar,i)=>bar.onclick=()=>{index=i;focus();});root.focus();focus();}

function makeDraggable(el,bounds,onDrop){let startX=0,startY=0;el.onpointerdown=e=>{e.preventDefault();startX=e.clientX;startY=e.clientY;el.setPointerCapture(e.pointerId);el.classList.add('dragging');};el.onpointermove=e=>{if(!el.hasPointerCapture(e.pointerId))return;el.style.transform=`translate(${e.clientX-startX}px,${e.clientY-startY}px)`;};el.onpointerup=e=>{if(!el.hasPointerCapture(e.pointerId))return;el.releasePointerCapture(e.pointerId);el.classList.remove('dragging');el.style.transform='';onDrop(e.clientX,e.clientY);};}
function makeSortable(list,say){let dragged=null;[...list.children].forEach(item=>{item.onpointerdown=e=>{dragged=item;item.setPointerCapture(e.pointerId);item.classList.add('dragging');};item.onpointermove=e=>{if(!dragged)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.sortable-list button');if(target&&target!==dragged)list.insertBefore(dragged,e.clientY<target.getBoundingClientRect().top+target.offsetHeight/2?target:target.nextSibling);};item.onpointerup=e=>{item.releasePointerCapture(e.pointerId);item.classList.remove('dragging');dragged=null;say('顺序已更新，可继续拖动');};});}
function makeFreeMove(node,canvas,say){node.onpointerdown=e=>{node.setPointerCapture(e.pointerId);node.dataset.dx=e.clientX-node.offsetLeft;node.dataset.dy=e.clientY-node.offsetTop;};node.onpointermove=e=>{if(!node.hasPointerCapture(e.pointerId))return;const x=Math.max(0,Math.min(canvas.clientWidth-node.offsetWidth,e.clientX-Number(node.dataset.dx))),y=Math.max(0,Math.min(canvas.clientHeight-node.offsetHeight,e.clientY-Number(node.dataset.dy)));node.style.left=`${x}px`;node.style.top=`${y}px`;canvas.classList.toggle('aligned',Math.abs(x-(canvas.clientWidth-node.offsetWidth)/2)<12);};node.onpointerup=e=>{node.releasePointerCapture(e.pointerId);say(canvas.classList.contains('aligned')?'已吸附到中心参考线':'节点位置已更新');};}
function makeResize(box,handle,say){handle.onpointerdown=e=>{e.preventDefault();handle.setPointerCapture(e.pointerId);handle.dataset.x=e.clientX;handle.dataset.y=e.clientY;handle.dataset.w=box.offsetWidth;handle.dataset.h=box.offsetHeight;};handle.onpointermove=e=>{if(!handle.hasPointerCapture(e.pointerId))return;const w=Math.max(140,Math.min(260,Number(handle.dataset.w)+e.clientX-Number(handle.dataset.x))),h=Math.max(80,Math.min(160,Number(handle.dataset.h)+e.clientY-Number(handle.dataset.y)));box.style.width=`${w}px`;box.style.height=`${h}px`;box.querySelector('.size-label').textContent=`${Math.round(w)} × ${Math.round(h)}`;};handle.onpointerup=e=>{handle.releasePointerCapture(e.pointerId);say(`尺寸已调整为 ${box.querySelector('.size-label').textContent}`);};}
function runProgress(root,say){const bar=root.querySelector('.progress-demo i'),label=root.querySelector('.progress-demo span');bar.style.width='0';let n=0;const timer=setInterval(()=>{n+=4;bar.style.width=`${n}%`;label.textContent=`${n}%`;if(n>=100){clearInterval(timer);say('导入完成');}},35);}
function makeBrush(chart,say){let start=0;const range=chart.querySelector('.brush-range');chart.onpointerdown=e=>{const r=chart.getBoundingClientRect();start=e.clientX-r.left;chart.setPointerCapture(e.pointerId);range.style.left=`${start}px`;range.style.width='0';};chart.onpointermove=e=>{if(!chart.hasPointerCapture(e.pointerId))return;const x=e.clientX-chart.getBoundingClientRect().left;range.style.left=`${Math.min(start,x)}px`;range.style.width=`${Math.abs(x-start)}px`;};chart.onpointerup=e=>{chart.releasePointerCapture(e.pointerId);say('已放大所选时间范围');};chart.querySelector('button').onclick=()=>{range.style.width='0';say('已恢复全部范围');};}
function drill(root,region,say){root.querySelector('.drill-crumb span').textContent=`› ${region}`;const names=region==='华东'?['上海','浙江','江苏']:region==='华南'?['广东','福建','海南']:['北京','河北','山东'];root.querySelector('.drill-bars').innerHTML=names.map((name,i)=>`<button style="--h:${75-i*15}%">${name}</button>`).join('');say(`已下钻到：${region}`);}

function copyText(text){navigator.clipboard?.writeText(text).then(showToast).catch(()=>{const input=document.createElement("textarea");input.value=text;document.body.append(input);input.select();document.execCommand("copy");input.remove();showToast();});}
