document.querySelectorAll("[data-copy]").forEach(button=>button.addEventListener("click",()=>copyText(button.dataset.copy)));
const searchDialog=document.querySelector('#search-dialog'),globalSearch=document.querySelector('#global-search'),searchResults=document.querySelector('#search-results');
function renderSearch(query=''){const keyword=query.trim().toLowerCase(),tokens=keyword.split(/\s+/).filter(Boolean),results=(keyword==='__favorites__'?searchIndex.filter(item=>favorites.has(itemId(item.groupIndex,item.itemIndex))):keyword==='__recent__'?recent.map(id=>{const [groupIndex,itemIndex]=id.split('-').map(Number);return searchIndex.find(item=>item.groupIndex===groupIndex&&item.itemIndex===itemIndex);}).filter(Boolean):keyword?searchIndex.filter(item=>{const text=[item.name,item.en,item.when,item.group,item.category].join(' ').toLowerCase();return tokens.some(token=>text.includes(token));}):searchIndex.slice(0,8)).slice(0,16);searchResults.innerHTML=results.length?results.map(item=>`<button data-search-go="${item.groupIndex}-${item.itemIndex}"><span><b>${item.name}</b><small>${item.en}</small></span><em>${item.group} · ${item.category}</em></button>`).join(''):`<p>${keyword==='__favorites__'?'还没有收藏组件':keyword==='__recent__'?'还没有浏览记录':'没有找到相关组件'}</p>`;searchResults.querySelectorAll('[data-search-go]').forEach(button=>button.onclick=()=>{[currentGroup,currentItem]=button.dataset.searchGo.split('-').map(Number);closeSearch();render();window.scrollTo({top:document.querySelector('.content').offsetTop-75,behavior:'smooth'});});}
function openSearch(){searchDialog.hidden=false;renderSearch();requestAnimationFrame(()=>{searchDialog.classList.add('open');globalSearch.focus();});}
function closeSearch(){searchDialog.classList.remove('open');setTimeout(()=>searchDialog.hidden=true,150);}
document.querySelector('#search-trigger').onclick=openSearch;globalSearch.oninput=()=>renderSearch(globalSearch.value);searchDialog.onclick=e=>{if(e.target===searchDialog)closeSearch();};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if(e.key==='Escape'&&!searchDialog.hidden)closeSearch();});
document.querySelector('#library-count').textContent=searchIndex.length+' 个模式';
document.querySelectorAll('[data-task]').forEach(button=>button.onclick=()=>{openSearch();const query=taskQueries[button.dataset.task];globalSearch.value=query.startsWith('__')?'':query;renderSearch(query);});
render();
